// === Tab: sketch ===
/**
 *
 * Opening Titles for 2001: A Space Odyssey
 * Code by Dave Pagurek
 *
 * Audio by Kevin McLeod, CC Attribution 3.0
 * https://en.wikipedia.org/wiki/File:Richard_Strauss_-_Also_Sprach_Zarathustra.ogg
 *
 * The original titles, for reference: https://www.youtube.com/watch?v=Xyqg--pi2wY
 *
 **/

// Just a pass-through vertex shader, nothing fancy here
const vert = `attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aTexCoord;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec2 vVertTexCoord;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertTexCoord = aTexCoord;
  }
`

const frag = `precision mediump float;
  varying highp vec2 vVertTexCoord;

  uniform float risePercent;
  uniform float time;

  const int NUM_STOPS = 6;
  vec3 sunGradientColors[NUM_STOPS];
  float sunGradientLocs[NUM_STOPS];

  // Noise functions
  // https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
  float rand(float n) {
    return fract(sin(n) * 43758.5453123);
  }
  float rand(vec2 n) { 
    return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
  }
  float noise(float p) {
    float fl = floor(p);
    float fc = fract(p);
    return mix(rand(fl), rand(fl + 1.0), fc);
  }
  float noise(vec2 n) {
    const vec2 d = vec2(0.0, 1.0);
    vec2 b = floor(n);
    vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
    return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
  }

  // Linear gradient implementation
  vec3 sunGradient(float t) {
    if (t < sunGradientLocs[0]) {
      return sunGradientColors[0];
    } else if (t >= sunGradientLocs[NUM_STOPS - 1]) {
      return sunGradientColors[NUM_STOPS - 1];
    }

    // Find the colors immediately before/after the current location 
    float prevT = sunGradientLocs[0];
    float nextT = sunGradientLocs[1];
    vec3 prevColor = sunGradientColors[0];
    vec3 nextColor = sunGradientColors[1];
    for (int i = 1; i < NUM_STOPS; i++) {
      if (sunGradientLocs[i] <= t) {
        prevT = sunGradientLocs[i];
        prevColor = sunGradientColors[i];
        if (i == NUM_STOPS - 1) {
          nextT = prevT;
          nextColor = prevColor;
        } else {
          nextT = sunGradientLocs[i+1];
          nextColor = sunGradientColors[i+1];
        }
      } else {
        break;
      }
    }

    // Linearly mix between them
    return mix(
      prevColor,
      nextColor,
      (t - prevT) / (nextT - prevT)
    );
  }

  void main() {
    // Colors in the sun gradient. There's a bit of green in there! Weird eh?
    sunGradientColors[0] = vec3(1., 1., 1.);
    sunGradientLocs[0] = 0.1;
    sunGradientColors[1] = vec3(255., 208., 196.)/255.;
    sunGradientLocs[1] = 0.11;
    sunGradientColors[2] = vec3(235., 163., 124.)/255. * 0.8;
    sunGradientLocs[2] = 0.15;
    sunGradientColors[4] = vec3(101., 161., 135.)/255. * 0.4;
    sunGradientLocs[4] = 0.21 + risePercent * 0.05;
    sunGradientColors[5] = vec3(0., 0., 0.);
    sunGradientLocs[5] = 0.28 + risePercent * 0.1;
    sunGradientColors[3] = (sunGradientColors[2]+sunGradientColors[4])/2.;
    sunGradientLocs[3] = 0.18 + risePercent * 0.01;

    // This is going to be the color of the current pixel
    vec3 color = vec3(0., 0., 0.);

    /////////////////////////////////////////////////////////////////////
    // Sun
    /////////////////////////////////////////////////////////////////////

    vec2 sunCoord = vec2(0.5, 0.5 - risePercent * 0.25);
    float distToSun = distance(vVertTexCoord, sunCoord);
    float angleToSun = atan(
      vVertTexCoord.y - sunCoord.y,
      vVertTexCoord.x - sunCoord.x
    );

    // Stretch the gradient a bit based on the angle to the sun to create
    // subtle flare lines.
    // Only do this if the distance to the sun is greater than the first
    // gradient stop's distance so the sun remains a circle
    float offset = mix(
      0.,
      1.5
        + sin(angleToSun * 8. + time) // small time variation
        + risePercent * (2.5 + sin(time*1.3)) * sin(-1. + angleToSun+time * 0.5),
      smoothstep(0., 1., clamp((distToSun - sunGradientLocs[0])*8., 0., 1.))
    );
    color = sunGradient(distToSun + 0.01*offset);

    /////////////////////////////////////////////////////////////////////
    // Stars
    /////////////////////////////////////////////////////////////////////

    // Take a narrow slice of high frequency noise
    color += smoothstep(
      0.98,
      0.99,
      noise(vVertTexCoord*800.)
    );

    /////////////////////////////////////////////////////////////////////
    // Earth
    /////////////////////////////////////////////////////////////////////

    vec2 earthCoord = vec2(0.5, 0.8 + risePercent * 0.1);
    float distToEarth = distance(vVertTexCoord, earthCoord);
    float angleToEarth = atan(
      vVertTexCoord.y - earthCoord.y,
      vVertTexCoord.x - earthCoord.x
    );

    if (distToEarth < 0.4) {
      // Compute an approximate normal for the sphere
      vec3 normal = normalize(mix(
        vec3(0., 0., 1.),
        vec3(normalize(vVertTexCoord - earthCoord), 0.),
        pow(distToEarth / 0.4, 2.)
      ));
      vec3 lightDir = -normalize(vec3(earthCoord, 0.) - vec3(sunCoord, -0.7));

      // Shading is standard Lambertian shading (same as what p5's lights use)
      float lambertian = max(dot(lightDir, normal), 0.0);

      vec3 earthColor = lambertian * ( 
        // Use noise to mix between land and water
        mix(
          vec3(150., 181., 181.)/255., // water
          vec3(101., 117., 106.)/255., // land
          smoothstep(
            0.6,
            0.7,
            // Base noise: gets the overall land shape
            noise(vec2(
              21. + 3.*sin(2.*angleToEarth+0.5)+2.*distToEarth,
              200. + 45.*distToEarth
            ))
            // Add some small but high-frequency noise to make the edge between
            // land and water less smooth
            + 0.1*noise(vec2(
              21. + 3.*sin(20.*angleToEarth)+2.*distToEarth,
              200. + 450.*distToEarth
            ))
          )
        )

        // clouds: just more noise
        + 0.2 * smoothstep(
          0.,
          1.,
          noise(vec2(5.*angleToEarth + time * 0.5, time * 0.1 + 100.*distToEarth))
        )
      );
      color = mix(earthColor, color, clamp((distToEarth - 0.398)/0.002, 0., 1.));
    }

    /////////////////////////////////////////////////////////////////////
    // Atmosphere
    /////////////////////////////////////////////////////////////////////

    // Add some glow based on the distance to the edge of the earth
    float atmosphere =
      (1. - smoothstep(0., 0.02, abs(distToEarth - 0.4)))
      * (1. - smoothstep(0., ${Math.PI/2}, abs(angleToEarth+${Math.PI/2})));
    color += (0.5 + risePercent*0.2)*vec3(109., 165., 214.)/255. * atmosphere;

    /////////////////////////////////////////////////////////////////////
    // Glare
    /////////////////////////////////////////////////////////////////////

    // Add a simple radial gradient on top of everything
    color += mix(
      vec3(74., 54., 40.)/255. * smoothstep(0.05, 0.2, clamp(risePercent, 0.05, 0.2)),
      vec3(0., 0., 0.),
      clamp(distToSun * 2. * (1. - 0.6 * risePercent), 0., 1.)
    );

    gl_FragColor = vec4(color, 1.);
  }
`

let sunShader
let textCanvas
let audio

function preload(){
  //audio = loadSound('http://upload.wikimedia.org/wikipedia/commons/f/fc/Richard_Strauss_-_Also_Sprach_Zarathustra.ogg')
}

function setup() {
  createCanvas(1112, 834, WEBGL)
  sunShader = createShader(vert, frag)
  textCanvas = createGraphics(width, height)
  textCanvas.pixelDensity(pixelDensity())

  //audio = createAudio('https://openprocessing.org/sketch/1465351/files/upload.wikimedia.org/wikipedia/commons/f/fc/Richard_Strauss_-_Also_Sprach_Zarathustra.ogg')
  //audio.elt.addEventListener('seeked', () => audio.play())
  //audio.time(45) // skip ahead to the climax, we dont have all day!
	//audio.play()
}

function draw() {
  background(100)

  const risePercent = Ease.easeInOutQuad(constrain(millis() / 35000, 0, 1))

  rectMode(CENTER)
  imageMode(CENTER)
  noStroke()
  push()
  shader(sunShader)
  sunShader.setUniform('risePercent', risePercent);
  sunShader.setUniform('time', millis() / 1000);
  rect(0, 0, width, height)
  pop()

  textCanvas.clear()
  textCanvas.push()
  textCanvas.textAlign(CENTER, BOTTOM)
  textCanvas.fill(255)
  textCanvas.noStroke()
  textCanvas.textSize(45)
  textCanvas.textFont('Inter')
  textCanvas.text('2001: A SPACE ODYSSEY', width/2, height * 0.978)
  textCanvas.pop()

  if (risePercent > 0.9) {
    image(textCanvas, 0, 0)
  }
}

// save jpg
let lapse = 0;    // mouse timer



// === Tab: ease ===
// Some easing functions
window.Ease = {
  // no easing, no acceleration
  linear: t => t,
  // accelerating from zero velocity
  easeInQuad: t => t*t,
  // decelerating to zero velocity
  easeOutQuad: t => t*(2-t),
  // acceleration until halfway, then deceleration
  easeInOutQuad: t => t<.5 ? 2*t*t : -1+(4-2*t)*t,
  // accelerating from zero velocity 
  easeInCubic: t => t*t*t,
  // decelerating to zero velocity 
  easeOutCubic: t => (--t)*t*t+1,
  // acceleration until halfway, then deceleration 
  easeInOutCubic: t => t<.5 ? 4*t*t*t : (t-1)*(2*t-2)*(2*t-2)+1,
  // accelerating from zero velocity 
  easeInQuart: t => t*t*t*t,
  // decelerating to zero velocity 
  easeOutQuart: t => 1-(--t)*t*t*t,
  // acceleration until halfway, then deceleration
  easeInOutQuart: t => t<.5 ? 8*t*t*t*t : 1-8*(--t)*t*t*t,
  // accelerating from zero velocity
  easeInQuint: t => t*t*t*t*t,
  // decelerating to zero velocity
  easeOutQuint: t => 1+(--t)*t*t*t*t,
  // acceleration until halfway, then deceleration 
  easeInOutQuint: t => t<.5 ? 16*t*t*t*t*t : 1+16*(--t)*t*t*t*t,
  easeInElastic: t => {
    const c4 = (2 * Math.PI) / 3

    return t === 0
      ? 0
      : t === 1
      ? 1
      : -Math.pow(2, 10 * t - 10) * Math.sin((t * 10 - 10.75) * c4)
  },
  easeOutElastic: t => {
    var c4 = (2 * Math.PI) / 3
    return t === 0
      ? 0
      : t === 1
      ? 1
      : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1
  },

  easeInOutElastic: t => {
    var s = 2 * t - 1 // remap: [0,0.5] -> [-1,0]
    var k = ((80 * s - 9) * Math.PI) / 18 // and    [0.5,1] -> [0,+1]
    if (s < 0) return -0.5 * Math.pow(2, 10 * s) * Math.sin(k)
    else return 1 + 0.5 * Math.pow(2, -10 * s) * Math.sin(k)
  },
}

